Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int INF = INT_MAX;
const int MAXN = 10001;

struct Edge {
    int v, rev, cap, cost;
};

vector<Edge> g[MAXN];
int nodeCnt;
int dist[MAXN], pot[MAXN], level[MAXN], cur[MAXN];
bool used[MAXN];

int addNodes(int cnt) {
    while (cnt--) g[nodeCnt++].clear();
    return nodeCnt - 1;
}

void addEdge(int u, int v, int cap, int cost) {
    g[u].push_back({v, (int)g[v].size(), cap, cost});
    g[v].push_back({u, (int)g[u].size() - 1, 0, -cost});
}

bool dijkstra(int s, int t) {
    fill(dist, dist + nodeCnt, INF);
    fill(used, used + nodeCnt, false);

    set<pair<int,int>> pq;
    dist[s] = 0;
    pq.insert({0, s});

    while (!pq.empty()) {
        auto curPair = *pq.begin();
        pq.erase(pq.begin());

        int du = curPair.first;
        int u = curPair.second;

        if (used[u]) continue;
        used[u] = true;

        for (const Edge &e : g[u]) {
            int v = e.v;
            if (!e.cap || used[v]) continue;

            int nd = du + pot[u] + e.cost - pot[v];
            if (dist[v] > nd) {
                pq.erase({dist[v], v});
                dist[v] = nd;
                pq.insert({nd, v});
            }
        }
    }

    return used[t];
}

bool buildLevelGraph(int s, int t) {
    fill(level, level + nodeCnt, 0);
    queue<int> q;
    q.push(s);
    level[s] = 1;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (const Edge &e : g[u]) {
            int v = e.v;
            if (!e.cap || level[v]) continue;

            if (dist[v] == dist[u] + e.cost - pot[v] + pot[u]) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }

    return level[t] != 0;
}

int dfs(int u, int t, int f) {
    if (u == t) return f;

    int sent = 0;
    for (int &i = cur[u]; i < (int)g[u].size(); ++i) {
        Edge &e = g[u][i];
        int v = e.v;

        if (!e.cap || level[v] != level[u] + 1) continue;
        if (dist[v] != dist[u] + e.cost - pot[v] + pot[u]) continue;

        int ret = dfs(v, t, min(f, e.cap));
        if (ret) {
            sent += ret;
            f -= ret;
            e.cap -= ret;
            g[v][e.rev].cap += ret;
            if (!f) break;
        }
    }

    return sent;
}

pair<int,int> minCostFlow(int s, int t, int maxFlow) {
    int flow = 0, cost = 0;
    fill(pot, pot + nodeCnt, 0);

    while (dijkstra(s, t)) {
        int phaseFlow = 0;

        while (buildLevelGraph(s, t)) {
            fill(cur, cur + nodeCnt, 0);
            int df = dfs(s, t, maxFlow);
            maxFlow -= df;
            phaseFlow += df;
            if (!maxFlow) break;
        }

        flow += phaseFlow;
        cost += (dist[t] + pot[t]) * phaseFlow;

        for (int i = 0; i < nodeCnt; ++i)
            if (dist[i] != INF) pot[i] += dist[i];

        if (!maxFlow) break;
    }

    return {flow, cost};
}

int main() {
    int n, m, k, c, d;
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);

    nodeCnt = 0;
    int L = max(n, k) * 2;

    addNodes(L * n);
    int s = addNodes(1);
    int t = addNodes(1);

    for (int j = 0; j < k; ++j) {
        int a;
        scanf("%d", &a);
        --a;
        addEdge(s, a, 1, 0);
    }

    for (int z = 0; z < m; ++z) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u;
        --v;

        for (int i = 0; i + 1 < L; ++i) {
            int u1 = u + i * n;
            int v1 = v + (i + 1) * n;
            int u2 = u + (i + 1) * n;
            int v2 = v + i * n;

            for (int j = 0; j < k; ++j) {
                int w = c + d * (2 * j + 1);
                addEdge(u1, v1, 1, w);
                addEdge(v2, u2, 1, w);
            }
        }
    }

    for (int i = 0; i + 1 < L; ++i) {
        for (int j = 0; j < n; ++j) {
            int u = j + i * n;
            int v = j + (i + 1) * n;
            addEdge(u, v, INF, c);
        }
    }

    for (int i = 0; i < L; ++i)
        addEdge(i * n, t, INF, 0);

    printf("%d\n", minCostFlow(s, t, INF).second);
    return 0;
}
